CREATE TABLE workflows(id TEXT PRIMARY KEY,title TEXT NOT NULL,context_json TEXT NOT NULL CHECK(json_valid(context_json)),created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE workflow_versions(workflow_id TEXT NOT NULL REFERENCES workflows(id),revision INTEGER NOT NULL CHECK(revision>0),plan_json TEXT NOT NULL CHECK(json_valid(plan_json)),digest TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(workflow_id,revision));
CREATE TABLE workflow_nodes(workflow_id TEXT NOT NULL,revision INTEGER NOT NULL,node_id TEXT NOT NULL,node_json TEXT NOT NULL CHECK(json_valid(node_json)),PRIMARY KEY(workflow_id,revision,node_id),FOREIGN KEY(workflow_id,revision) REFERENCES workflow_versions(workflow_id,revision));
CREATE TABLE workflow_edges(workflow_id TEXT NOT NULL,revision INTEGER NOT NULL,source TEXT NOT NULL,target TEXT NOT NULL,CHECK(source<>target),PRIMARY KEY(workflow_id,revision,source,target),FOREIGN KEY(workflow_id,revision,source) REFERENCES workflow_nodes(workflow_id,revision,node_id),FOREIGN KEY(workflow_id,revision,target) REFERENCES workflow_nodes(workflow_id,revision,node_id));
CREATE TABLE execution_runs(id TEXT PRIMARY KEY,workflow_id TEXT NOT NULL,revision INTEGER NOT NULL,mode TEXT NOT NULL CHECK(mode IN('DRY_RUN','SANDBOX_EXECUTION','APPROVED_EXECUTION')),status TEXT NOT NULL CHECK(status IN('CREATED','PLANNED','VALIDATING','READY','WAITING_APPROVAL','QUEUED','RUNNING','SUCCEEDED','FAILED','CANCELLED','BLOCKED','INTERRUPTED','RECOVERABLE')),request_key TEXT NOT NULL,plan_digest TEXT NOT NULL,workspace TEXT NOT NULL,owner_pid INTEGER,owner_token TEXT,last_error TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,started_at INTEGER,finished_at INTEGER,UNIQUE(workflow_id,revision,request_key),FOREIGN KEY(workflow_id,revision) REFERENCES workflow_versions(workflow_id,revision));
CREATE TABLE execution_steps(id TEXT PRIMARY KEY,execution_id TEXT NOT NULL REFERENCES execution_runs(id),node_id TEXT NOT NULL,attempt INTEGER NOT NULL CHECK(attempt>0),status TEXT NOT NULL CHECK(status IN('QUEUED','RUNNING','SUCCEEDED','FAILED','CANCELLED','BLOCKED','INTERRUPTED','SKIPPED')),idempotency_key TEXT NOT NULL UNIQUE,side_effect TEXT NOT NULL,input_digest TEXT NOT NULL,output_digest TEXT,output_json TEXT CHECK(output_json IS NULL OR json_valid(output_json)),error_type TEXT NOT NULL DEFAULT '',started_at INTEGER NOT NULL,finished_at INTEGER,UNIQUE(execution_id,node_id,attempt));
CREATE TABLE execution_events(sequence INTEGER PRIMARY KEY,workflow_id TEXT NOT NULL REFERENCES workflows(id),execution_id TEXT REFERENCES execution_runs(id),node_id TEXT,event TEXT NOT NULL,data_json TEXT NOT NULL CHECK(json_valid(data_json)),created_at INTEGER NOT NULL);
CREATE TABLE execution_approvals(id TEXT PRIMARY KEY,execution_id TEXT NOT NULL REFERENCES execution_runs(id),plan_digest TEXT NOT NULL,scope_digest TEXT NOT NULL,scope_json TEXT NOT NULL CHECK(json_valid(scope_json)),decision TEXT NOT NULL CHECK(decision IN('APPROVED','DENIED')),expires_at INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE execution_checkpoints(execution_id TEXT NOT NULL REFERENCES execution_runs(id),node_id TEXT NOT NULL,state TEXT NOT NULL,data_json TEXT NOT NULL CHECK(json_valid(data_json)),updated_at INTEGER NOT NULL,PRIMARY KEY(execution_id,node_id));
CREATE TABLE execution_evidence(id TEXT PRIMARY KEY,execution_id TEXT NOT NULL REFERENCES execution_runs(id),node_id TEXT NOT NULL,capability_id TEXT,capability_version TEXT,adapter_type TEXT NOT NULL,evidence_reference TEXT NOT NULL,evidence_hash TEXT NOT NULL,byte_count INTEGER NOT NULL,verification_policy TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(execution_id,node_id));
CREATE TABLE runtime_observations(id TEXT PRIMARY KEY,protocol TEXT NOT NULL,metadata_json TEXT NOT NULL CHECK(json_valid(metadata_json)),observed_at INTEGER NOT NULL);
CREATE UNIQUE INDEX workflow_one_active ON execution_runs(workflow_id) WHERE status IN('QUEUED','RUNNING','WAITING_APPROVAL');
CREATE INDEX execution_events_cursor ON execution_events(execution_id,sequence);
CREATE INDEX execution_runs_workflow ON execution_runs(workflow_id,created_at);
CREATE INDEX execution_steps_latest ON execution_steps(execution_id,node_id,attempt);
INSERT INTO schema_migrations(version,name) VALUES(10,'autonomous_orchestration');
PRAGMA user_version=10;
